{
  "packet_id": "H6-T03-1",
  "claim_id": "C011",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C011.component",
    "value": "Event dates, record-creation dates and attachment dates must be distinguished explicitly.",
    "scope": "The dates collected for the order-level investigation; the mapping does not assert that these dates necessarily differ.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P009 explicitly requires collecting and distinguishing these three types of dates."
    }
  },
  "signal_basis": {
    "component_id": "C011.signal_basis",
    "value": "Collect distinct event, record-creation and attachment dates and examine whether linked, appropriately authorized approval records demonstrate approval before order placement.",
    "scope": "Order-level documentary investigation. These observations are proposed tests, assumed performed for this judgment, rather than reported findings.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the date collection, temporal and authority checks, and proposed-observation qualification."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C011.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The procedural claim is supported without an unresolved empirical bridging relation."
    }
  },
  "rationale": "Assessing whether approval preceded placement requires preserving which event each date describes. Record creation and attachment dates describe separate events and cannot automatically substitute for the approval event date. Explicitly distinguishing their meanings is warranted even when their values coincide.",
  "uncertainty": "The distinction alone does not establish timestamp reliability or timely approval for any order.",
  "anomalies": []
}
